const long long INF = LLONG_MAX;

int n, g, k;
vector<long long> a, s, ssq;
vector<vector<long long>> dp;

long long cost(int l, int r) {
    if (k == 1) {
        int m = (l + r) >> 1;
        long long lc = m - l + 1;
        long long ls = s[m] - s[l-1];
        long long rs = s[r] - s[m];
        long long rc = r - m;
        return a[m]*lc - ls + rs - a[m]*rc;
    } else {
        long long len = r - l + 1;
        long long sum = s[r] - s[l-1];
        long long sumsq = ssq[r] - ssq[l-1];
        long long v0 = sum / len;
        long long best = INF;
        for (long long v = v0; v <= v0 + 1; ++v) {
            long long val = sumsq - 2LL*v*sum + len*v*v;
            if (val < best) best = val;
        }
        return best;
    }
}

void comp(int gg, int l, int r, int optl, int optr) {
    if (l > r) return;
    int mid = (l + r) >> 1;
    pair<long long,int> best = {INF, -1};
    int ub = min(mid - 1, optr);
    if (optl <= ub) {
        for (int t = optl; t <= ub; ++t) {
            long long cand = dp[gg-1][t];
            if (cand >= INF) continue;
            cand += cost(t+1, mid);
            if (cand < best.first) best = {cand, t};
        }
    }
    if (best.second == -1) best.second = optl;
    dp[gg][mid] = best.first;
    int opt = best.second;
    comp(gg, l, mid-1, optl, opt);
    comp(gg, mid+1, r, opt, optr);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> g >> k)) return 0;
    a.assign(n+1, 0);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    s.assign(n+1, 0);
    ssq.assign(n+1, 0);
    for (int i = 1; i <= n; ++i) {
        s[i] = s[i-1] + a[i];
        ssq[i] = ssq[i-1] + a[i]*a[i];
    }

    dp.assign(g+1, vector<long long>(n+1, INF));
    dp[0][0] = 0;

    for (int gg = 1; gg <= g; ++gg) {
        dp[gg][0] = 0;
        comp(gg, 1, n, 0, n-1);
    }

    cout << dp[g][n] << "\n";
}
